import { compose } from 'redux';

function withAuth<P>(Component: React.ComponentType<P>) {
  const Enhanced = (props: P) => {
    const { isAuthenticated } = useAuth();
    if (!isAuthenticated) return <div>Please log in</div>;
    return <Component {...props} />;
  };
  Enhanced.displayName = `withAuth(${Component.displayName ?? Component.name})`;
  return Enhanced;
}

function withLoading<P extends { isLoading?: boolean }>(
  Component: React.ComponentType<P>
) {
  const Enhanced = (props: P) => {
    if (props.isLoading) return <div>Loading...</div>;
    const { isLoading, ...rest } = props;
    return <Component {...(rest as P)} />;
  };
  Enhanced.displayName = `withLoading(${Component.displayName ?? Component.name})`;
  return Enhanced;
}

function withLogger<P>(Component: React.ComponentType<P>) {
  const Enhanced = (props: P) => {
    console.log(`${Component.displayName ?? Component.name} props:`, props);
    return <Component {...props} />;
  };
  Enhanced.displayName = `withLogger(${Component.displayName ?? Component.name})`;
  return Enhanced;
}

function Dashboard() {
  return <h1>Dashboard</h1>;
}
Dashboard.displayName = 'Dashboard';

// Manual composition (inside-out)
const EnhancedDashboard1 = withAuth(withLoading(withLogger(Dashboard)));

// Using compose (left-to-right)
const enhance = compose(withLogger, withLoading, withAuth);
const EnhancedDashboard2 = enhance(Dashboard);

// Both produce the same result
